window.MarketV3=(()=>{
'use strict';
const C=MarketCore,E=USTDecisionEngine,I=USTDecisionImport,$=s=>document.querySelector(s),e=C.esc;
const colors=['#177e93','#955a9b','#c07832','#638ba8'];
let lang='en',host=null,db=null,dbFailed=false,staged=null,loaders={},errors={};
const X={master:null,history:null,ust:null,masterTab:'explore',historyTab:'yield',q:'',categories:[],currencies:[],quote:'',ar:'',sort:'name',precision:'source',page:1,selection:[],watchlists:[],screens:[],notes:{},activeList:null,historyA:'UST 10Y',historyB:'UST 5Y',fxA:'USD/SGD',fxB:'CHF/SGD',start:'2006-10-01',end:'2026-08-01',curveFamily:'ust',curveA:'2026-08-01',curveB:'2021-08-01',fxMode:'level',events:true,scenario:0,horizon:12,ustQ:'',ustMin:'',ustMax:'',ustCoupon:'',ustYield:'',ustSort:'maturity',ustConvention:'',ustPositive:false,ustCompare:[],asof:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),feedType:'master'};
try{lang=localStorage.getItem('market-hub-language')||'en';const saved=JSON.parse(localStorage.getItem('market-hub-v3-workspace')||'{}');for(const k of ['selection','watchlists','screens','notes','ustCompare'])if(saved[k]&&typeof saved[k]==typeof X[k])X[k]=saved[k];}catch{}
if(!['en','zh-Hans','zh-Hant'].includes(lang))lang='en';
function t(en,sc,tc){if(lang==='en')return en;const v=sc?[sc,tc||sc]:MarketI18n[en];return v?v[lang==='zh-Hant'?1:0]:en;}
function loc(){return lang==='en'?'en-SG':lang==='zh-Hant'?'zh-TW':'zh-CN';}
function d(day){return C.validDate(day)?new Date(day+'T12:00:00+08:00').toLocaleDateString(loc(),{year:'numeric',month:'short',day:'numeric',timeZone:'Asia/Singapore'}):t('Unknown quote time');}
function n(v,dp=2){return C.finite(v)?v.toLocaleString(loc(),{minimumFractionDigits:dp,maximumFractionDigits:dp}):'—';}
function button(label,attrs='',cl='button'){return`<button class="${cl}" ${attrs}>${e(t(label))}</button>`;}
function option(v,label,selected){return`<option value="${e(v)}" ${v===selected?'selected':''}>${e(t(label))}</option>`;}
function label(name,control,wide=false){return`<label class="${wide?'wide':''}"><span>${e(t(name))}</span>${control}</label>`;}
function select(id,items,value){return`<select id="${id}">${items.map(([v,k])=>option(v,k,value)).join('')}</select>`;}
function input(id,value,type='text',extra=''){return`<input id="${id}" type="${type}" value="${e(value)}" ${extra}>`;}
function head(k,title,text){return`<div class="page-head"><div class="eyebrow">${e(t(k))}</div><h1>${e(t(title))}</h1><p>${e(text)}</p></div>`;}
function notice(text,good=false){return`<div class="source-notice ${good?'good':''}">${text}</div>`;}
function stats(items){return`<div class="stats-strip">${items.map(([a,b])=>`<div class="card"><strong>${e(a)}</strong><span>${e(t(b))}</span></div>`).join('')}</div>`;}
function link(url,text){let safe='#';try{const u=new URL(url,location.href);if(['https:','http:'].includes(u.protocol))safe=u.href;}catch{}return`<a href="${e(safe)}" target="_blank" rel="noopener noreferrer">${e(t(text))} ↗</a>`;}
function persist(){try{localStorage.setItem('market-hub-v3-workspace',JSON.stringify({selection:X.selection,watchlists:X.watchlists,screens:X.screens,notes:X.notes,ustCompare:X.ustCompare}));}catch{toast(t('Browser storage is unavailable; keep a workspace backup.','浏览器存储不可用，请下载工作区备份。','瀏覽器儲存不可用，請下載工作區備份。'));}}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4000);}
function openDB(){if(db)return Promise.resolve(db);return new Promise((resolve,reject)=>{const req=indexedDB.open('market-intelligence-v3',1);req.onupgradeneeded=()=>req.result.createObjectStore('snapshots');req.onsuccess=()=>{db=req.result;resolve(db);};req.onerror=()=>reject(req.error);});}
async function stored(key){try{const b=await openDB();return await new Promise((ok,no)=>{const r=b.transaction('snapshots').objectStore('snapshots').get(key);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});}catch{dbFailed=true;return null;}}
async function storeSnapshot(key,value){const b=await openDB();return new Promise((ok,no)=>{const tx=b.transaction('snapshots','readwrite');tx.objectStore('snapshots').put(value,key);tx.oncomplete=()=>ok();tx.onerror=()=>no(tx.error);});}
function validate(type,data){return type==='master'?C.validateMaster(data):type==='history'?C.validateHistory(data):C.validateUST(data);}
async function load(type){if(X[type]||loaders[type])return;loaders[type]=true;try{const bundled=window.MARKET_OFFLINE?.[type];if(bundled){X[type]=validate(type,bundled);return;}const local=await stored(type);if(local)X[type]=validate(type,local);else{const r=await fetch('data/'+type+'-v3.json');if(!r.ok)throw Error('HTTP '+r.status);X[type]=validate(type,await r.json());}}catch(err){errors[type]=String(err.message);}finally{loaders[type]=false;host?.render();}}
function loading(type){if(errors[type])return notice(e(t('This snapshot could not load.','此快照无法加载。','此快照無法載入。'))+' '+e(errors[type]))+button('Retry',`data-tool="retry" data-type="${type}"`);return`<div class="card" role="status">${e(t('Loading supplied snapshot…','正在加载用户提供快照…','正在載入使用者提供快照…'))}</div>`;}
function workspaceNote(){return dbFailed?notice(e(t('Browser snapshot storage is unavailable. Imports work for this session; download a backup.','本浏览器无法保存快照，导入只在本次会话有效，请下载备份。','本瀏覽器無法儲存快照，匯入只在本次工作階段有效，請下載備份。'))):'';}
function subnav(items,current,key){return`<div class="subnav" role="group" aria-label="${e(t(key==='historyTab'?'Historical yields & FX':'Security master'))}">${items.map(([id,name])=>button(name,`data-tool="tab" data-key="${key}" data-tab="${id}" aria-pressed="${id===current}"`,' '+(id===current?'active':''))).join('')}</div>`;}
function welcome(){return`<section class="welcome-tools" aria-label="Research tools">${[['master','Security master','8,466 source records','8,466 条来源记录','8,466 筆來源記錄'],['history','Historical yields & FX','Compare dates & curves','比较历史日期与曲线','比較歷史日期與曲線'],['ust','UST selection desk','Daily file & bond comparison','每日文件与债券比较','每日檔案與債券比較']].map(([v,title,en,sc,tc])=>`<button data-view="${v}"><b>${e(t(title))}</b><small>${e(t(en,sc,tc))} ↗</small></button>`).join('')}</section>`;}
function facets(key,title,values){const active=X[key];return`<details class="facet-box"><summary>${e(t(title))}${active.length?' · '+active.length:''}</summary><div class="facet-checks">${values.map(v=>`<label><input type="checkbox" data-facet="${key}" value="${e(v)}" ${active.includes(v)?'checked':''}>${e(t(v||'Category missing'))}</label>`).join('')}</div></details>`;}
function masterFilter(){return{q:X.q,categories:X.categories,currencies:X.currencies,quote:X.quote,ar:X.ar,ids:X.activeList?X.watchlists.find(w=>w.id===X.activeList)?.ids:undefined};}
function masterRows(){const f=C.filterMaster(X.master.records,masterFilter());return f.sort((a,b)=>{if(X.sort==='ar')return(b.ar??-Infinity)-(a.ar??-Infinity)||a.name.localeCompare(b.name);if(X.sort==='price')return(b.lastPrice??-Infinity)-(a.lastPrice??-Infinity)||a.name.localeCompare(b.name);return a.name.localeCompare(b.name);});}
function rawNum(r,key){const v=r.raw[key];if(v===null||v===undefined||v==='')return'<span class="num-missing">—</span>';const num=C.numeric(v);return e(X.precision==='source'||num===null?v:n(num,Number(X.precision)));}
function rowHTML(r){const chosen=X.selection.includes(r.id),starred=X.watchlists.some(w=>w.ids.includes(r.id));return`<article class="security-row"><label class="row-select"><input type="checkbox" data-pick="${e(r.id)}" aria-label="${e(t('Select')+' '+r.name)}" ${chosen?'checked':''}></label><div class="sec-name"><button class="security-title" data-detail="${e(r.id)}">${e(r.name)}</button><div class="security-id">${e(r.isin||r.securityNo||r.id)}</div><div class="quote-chip ${r.quoteStatus==='Crossed quote'?'bad':''}">${e(t(r.quoteStatus))}</div></div><div class="ccy">${e(r.currency||'—')} · ${e(t(r.category||'Category missing'))}</div><div class="last cell-number"><span class="label">${e(t('Last price'))}</span>${rawNum(r,'Last Price')}</div><div class="quotes cell-number"><span class="label">${e(t('Raw bid / ask'))}</span><span>${rawNum(r,'BID')} / ${rawNum(r,'ASK')}</span></div><div class="ar cell-number"><span class="label">${e(t('Source AR'))}</span><span>${rawNum(r,'Fixed AR(%)')}${r.raw['Fixed AR(%)']!==null?'%':''}</span></div><button class="star" data-tool="watch-one" data-id="${e(r.id)}" aria-label="${e(t('Add to watchlist')+' '+r.name)}">${starred?'★':'☆'}</button></article>`;}
function resultArea(){const rows=masterRows(),pages=Math.max(1,Math.ceil(rows.length/24));X.page=Math.min(X.page,pages);const page=rows.slice((X.page-1)*24,X.page*24),visible=new Set(rows.map(r=>r.id)),hidden=X.selection.filter(id=>!visible.has(id)).length;return`<div class="tools-row"><span class="count-line" id="master-count">${rows.length.toLocaleString(loc())} ${e(t('matching source rows','条符合的来源记录','筆符合的來源記錄'))} · ${X.page}/${pages}</span><div class="links">${button('Select visible page','data-tool="page-pick"','button ghost')}${button('Clear filters','data-tool="clear-filters"','button ghost')}</div></div><div class="sec-table-head"><span></span><span>${e(t('Name'))}</span><span>${e(t('Currency'))}</span><span>${e(t('Last price'))}</span><span>BID / ASK</span><span>${e(t('Source AR'))}</span><span>☆</span></div><div id="master-rows">${page.map(rowHTML).join('')||`<div class="empty">${e(t('No matches'))}</div>`}</div><div class="pager">${button('Previous',`data-tool="page" data-step="-1" ${X.page===1?'disabled':''}`)}<span>${X.page} / ${pages}</span>${button('Next',`data-tool="page" data-step="1" ${X.page===pages?'disabled':''}`)}</div><div class="selection-bar"><p><b>${X.selection.length} ${e(t('Selected'))}</b>${hidden?' · '+hidden+' '+e(t('hidden by filters','条被筛选隐藏','筆被篩選隱藏')):''}</p><div class="links">${button('Add to watchlist',`data-tool="watch" ${!X.selection.length?'disabled':''}`)}${button('Clear selection','data-tool="clear-selection"')}</div></div>`;}
function masterView(){const intro=head('Security master','Find securities. Keep the source.',t('A shared research universe for stocks, funds and bonds. Saved lists stay on this device.','股票、基金与债券共用一个研究主档。自选清单保存在当前设备。','股票、基金與債券共用一個研究主檔。自選清單儲存在目前裝置。'));if(!X.master)return intro+loading('master');const r=X.master.records;return intro+notice(e(t('Supplied ACE snapshot. Filename date','用户提供的 ACE 快照。文件名日期','使用者提供的 ACE 快照。檔名日期'))+': '+e(X.master.snapshot.filenameDate||'—')+' · '+e(t('Unknown quote time'))+'. '+e(t('Source AR is not confirmed borrowing capacity.','来源 AR 不是已确认的可借额度。','來源 AR 並非已確認的可借額度。')))+workspaceNote()+subnav([['explore','Explore'],['watchlists','Watchlists'],['screens','Saved screens'],['pivot','Pivot explorer'],['review','Data review']],X.masterTab,'masterTab')+(X.masterTab==='explore'?masterExplore():X.masterTab==='pivot'?masterPivot():X.masterTab==='review'?masterReview():masterSaved());}
function masterExplore(){const cats=[...new Set(X.master.records.map(r=>r.category||'Category missing'))].sort(),ccy=[...new Set(X.master.records.map(r=>r.currency))].sort();return`<div class="master-toolbar"><label class="sr-only" for="master-search">${e(t('Search name, ISIN or security number'))}</label><input id="master-search" class="search" value="${e(X.q)}" placeholder="${e(t('Search name, ISIN or security number'))}">${facets('categories','Category',cats)}${facets('currencies','Currency',ccy)}</div><details class="advanced-filters"><summary>${e(t('More filters & display'))}</summary><div class="tool-controls">${label('Quote status',select('master-quote',[['','Any'],...['Two-sided','Crossed quote','One-sided','Vendor error','No quote'].map(x=>[x,x])],X.quote))}${label('Source AR',select('master-ar',[['','Any AR'],['zero','Zero AR'],['missing','Missing AR'],['50','≥ 50%'],['70','≥ 70%'],['80','≥ 80%'],['90','≥ 90%']],X.ar))}${label('Sort by',select('master-sort',[['name','Name'],['price','Last price'],['ar','Source AR']],X.sort))}${label('Display precision',select('master-precision',[['source','Source precision'],['2','2 decimals'],['4','4 decimals']],X.precision))}</div></details>${X.activeList?notice(e(t('Viewing watchlist','正在查看自选清单','正在檢視自選清單'))+': '+e(X.watchlists.find(w=>w.id===X.activeList)?.name||'')+' '+button('Open full master','data-tool="full-master"','button ghost'),true):''}<div class="tools-row"><div class="segmented">${[...X.categories,...X.currencies].map(x=>`<span class="chip">${e(t(x))}</span>`).join('')}</div><div class="links">${button('Stocks & bond factsheets','data-view="directory"','button ghost')}${button('Save screen','data-tool="screen-save"','button ghost')}${button('Upload a refreshed snapshot','data-view="feeds"','button ghost')}</div></div><div id="master-result-area">${resultArea()}</div>`;}
function masterPivot(){const p=C.pivot(X.master.records);return stats([[n(p.total,0),'Source rows'],[p.currencies.length,'Currencies'],[p.cats.length,'Category'],[X.master.records.filter(r=>!r.category).length,'Category missing']])+`<div class="card"><h3>${e(t('Category × currency','类别 × 货币','類別 × 貨幣'))}</h3><p class="v3-caption">${e(t('Each count opens the contributing source rows. Counts are not portfolio values.','点击计数查看对应记录。计数并非投资组合市值。','點選計數檢視對應記錄。計數並非投資組合市值。'))}</p><div class="table-scroll"><table class="data-table"><thead><tr><th>${e(t('Category'))}</th>${p.currencies.map(c=>`<th>${e(c)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${p.cats.map(c=>`<tr><th>${e(t(c))}</th>${p.currencies.map(k=>`<td><button data-tool="drill" data-cat="${e(c)}" data-ccy="${e(k)}" ${p.counts[c][k]===0?'disabled':''}>${n(p.counts[c][k],0)}</button></td>`).join('')}<td>${n(Object.values(p.counts[c]).reduce((a,b)=>a+b,0),0)}</td></tr>`).join('')}<tr><th>Total</th>${p.currencies.map(k=>`<td>${n(X.master.records.filter(r=>(r.currency||'Unknown')===k).length,0)}</td>`).join('')}<th>${n(p.total,0)}</th></tr></tbody></table></div></div>`;}
function masterReview(){const rows=X.master.records,cross=rows.filter(r=>r.quoteStatus==='Crossed quote').length,missing=rows.filter(r=>r.ar===null).length,zero=rows.filter(r=>r.ar===0).length;return stats([[n(rows.length,0),'Source rows'],[cross,'Crossed quotes'],[missing,'Missing AR'],[zero,'Zero AR']])+`<div class="card"><h3>${e(t('Review the original observations','核对原始观测值','核對原始觀測值'))}</h3><p>${e(t('Last Price, BID and ASK are independent supplied fields. Crossed pairs remain unchanged. Missing values, zero and vendor errors remain distinct.','最新来源价、买价和卖价为独立字段。交叉报价保持原样，缺值、零值和来源错误分别保留。','最新來源價、買價和賣價為獨立欄位。交叉報價保持原樣，缺值、零值和來源錯誤分別保留。'))}</p><div class="links">${button('Crossed quotes','data-tool="review-cross"')}${button('Missing AR','data-tool="review-missing"')}${button('Zero AR','data-tool="review-zero"')}</div><div class="divider"></div><p>${e(t('CPN Rate is a source label with an unconfirmed metric mapping. Call dates are not maturity dates. Positive AR does not establish current eligibility.','CPN Rate 的指标含义未完成映射。赎回日不能视为到期日，正数 AR 也不能证明当前合资格。','CPN Rate 的指標含義尚未完成對應。贖回日不能視為到期日，正數 AR 也不能證明目前合資格。'))}</p><p class="snapshot-row">${e(X.master.snapshot.sourceFile)} · ${e(X.master.snapshot.sheet)} · ${e(X.master.snapshot.id)}</p><div class="links">${button('Download backup','data-tool="backup"')}${button('Data & uploads','data-view="feeds"')}</div></div>`;}
function masterSaved(){const watch=X.masterTab==='watchlists',items=watch?X.watchlists:X.screens;return`<div class="tool-intro">${e(watch?t('A watchlist stores chosen identities and notes. A saved screen stores filter rules.','自选清单保存选定证券与备注；已存筛选保存筛选规则。','自選清單儲存選定證券與備註；已存篩選儲存篩選規則。'):t('Saved screens rerun their rules against the current snapshot.','已存筛选会在当前快照上重新执行规则。','已存篩選會在目前快照上重新執行規則。'))}</div>${items.map(w=>`<article class="list-card"><h3>${e(w.name)}</h3><p>${watch?w.ids.length+' '+e(t('saved identities','个已存身份','個已存身分'))+' · '+w.ids.filter(id=>!X.master.records.some(r=>r.id===id)).length+' '+e(t('absent from current snapshot','个不在当前快照中','個不在目前快照中')):e(JSON.stringify(w.filters))}</p><p>${e(w.note||'')}</p><div class="links">${button('Open',`data-tool="saved-open" data-id="${e(w.id)}" data-kind="${watch?'watch':'screen'}"`)}${button('Remove',`data-tool="saved-remove" data-id="${e(w.id)}" data-kind="${watch?'watch':'screen'}"`,'button ghost')}</div></article>`).join('')||`<div class="empty">${e(t('No saved items yet. Select records in Explore to create a list.','尚未保存。请先在主档浏览页选择证券。','尚未儲存。請先在主檔瀏覽頁選擇證券。'))}</div>`}<div class="links">${button('Explore','data-tool="explore"')}${button('Download backup','data-tool="backup"')}${button('Restore backup','data-tool="restore"')}</div>`;}
function masterDetail(id){const r=X.master.records.find(x=>x.id===id);if(!r)return;const dir=host.getDirectory();const facts=[...(dir?.stocks||[]),...(dir?.bonds||[])].filter(x=>(x.isin||x.id)&& (x.isin||x.id)===r.isin);showDialog(r.name,`<div class="tags"><span class="tag">${e(r.currency||'—')}</span><span class="tag">${e(t(r.category||'Category missing'))}</span><span class="tag">${e(r.isin||r.securityNo||r.id)}</span></div>${notice(e(t('Quote timestamp and policy effective date are not supplied. Source values have not been reconciled into a valuation price.','未提供报价时间和政策生效日，来源价格尚未核对为估值价格。','未提供報價時間和政策生效日，來源價格尚未核對為估值價格。')))}${r.quoteStatus==='Crossed quote'?notice(e(t('BID exceeds ASK. The source has been preserved; review the quotation basis.','买价高于卖价，原始数据保持不变，请核对报价基准。','買價高於賣價，原始數據保持不變，請核對報價基準。'))):''}<h3>${e(t('Original raw fields'))}</h3><dl class="raw-grid">${C.fields.map(f=>`<div><dt>${e(f)}</dt><dd>${r.raw[f]===null||r.raw[f]===undefined?e(t('Missing')):e(r.raw[f])}</dd></div>`).join('')}</dl><h3>${e(t('Reference links'))}</h3><div class="links">${facts.map(x=>link(x.url,'Exact ISIN match')).join('')}${r.isin?link('https://www.google.com/search?q='+encodeURIComponent('"'+r.isin+'" Morningstar Bondsupermart'),'Search exact ISIN') :''}</div><p class="v3-caption">${e(t('Search links are discovery tools, not verified security mappings.','搜索链接仅供查找，不代表证券身份已核实。','搜尋連結僅供查找，不代表證券身分已核實。'))}</p><div class="divider"></div><label class="field">${e(t('Notes'))}<textarea id="security-note" maxlength="3000" data-id="${e(r.id)}">${e(X.notes[r.id]||'')}</textarea></label><div class="links">${button('Save','data-tool="note-save"')}${button('Add to watchlist',`data-tool="watch-one" data-id="${e(r.id)}"`)}</div><p class="snapshot-row">${e(X.master.snapshot.sourceFile)} · ${e(X.master.snapshot.sheet)}!${r.sourceRow} · ${e(X.master.snapshot.id)}</p>`);}
const events=[{date:'2008-11-25',label:'QE1',url:'https://www.federalreserve.gov/newsevents/pressreleases/2008all.htm'},{date:'2020-03-15',label:'COVID response',url:'https://www.federalreserve.gov/newsevents/pressreleases/monetary20200315a.htm'},{date:'2022-03-16',label:'Fed hikes',url:'https://www.federalreserve.gov/newsevents/pressreleases/monetary20220316a.htm'}];
function addMonths(day,m){const d0=new Date(day+'T12:00:00Z');d0.setUTCMonth(d0.getUTCMonth()+m);return d0.toISOString().slice(0,10);}
function lineChart(lines,{title='',unit='%',curve=false,scenario=null}={}){
 const mobile=matchMedia('(max-width:760px)').matches,scale=Number(document.documentElement.style.getPropertyValue('--text-scale'))||1,large=document.documentElement.dataset.displayCharts==='large',W=mobile?400:900,H=large?(mobile?390:480):(mobile?285:340),L=Math.ceil(48*scale),R=16,T=Math.ceil(40*scale),B=Math.ceil(40*scale);
 const all=lines.flatMap(s=>s.points).filter(p=>C.finite(p[1]));if(!all.length)return`<div class="empty">${e(t('No observations for these dates.','所选日期没有观测值。','所選日期沒有觀測值。'))}</div>`;
 const xval=v=>curve?Number(v):Date.parse(v+'T00:00:00Z');let xmin=Math.min(...all.map(p=>xval(p[0]))),xmax=Math.max(...all.map(p=>xval(p[0]))),min=Math.min(...all.map(p=>p[1])),max=Math.max(...all.map(p=>p[1]));
 if(scenario){xmax=Math.max(xmax,xval(scenario.end[0]));min=Math.min(min,scenario.end[1]);max=Math.max(max,scenario.end[1]);}
 if(xmin===xmax)xmax=xmin+1;if(min===max){min-=.1;max+=.1;}const span=max-min;min-=span*.15;max+=span*.15;
 const xx=x=>L+(xval(x)-xmin)/(xmax-xmin)*(W-L-R),yy=y=>H-B-(y-min)/(max-min)*(H-T-B);
 let svg=`<svg class="v3-chart" viewBox="0 0 ${W} ${H}" role="img" tabindex="0" aria-label="${e(title)}"><title>${e(title+' · '+unit)}</title><desc>${e(t('Exact observations and dates are available in the data table below.','下方数据表提供精确观测值及日期。','下方數據表提供精確觀測值及日期。'))}</desc>`;
 for(let i=0;i<5;i++){const v=min+(max-min)*i/4,y=yy(v);svg+=`<line class="axis-line" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text x="${L-8}" y="${y+4}" text-anchor="end">${e(n(v,unit==='%'?2:unit==='100'?0:3))}${unit==='%'?'%':''}</text>`;}
 if(curve){const ticks=(xmax>35?[0,10,20,30,40,50]:[0,5,10,15,20,25,30]).filter(v=>v>=xmin&&v<=xmax);for(const v of ticks)svg+=`<text x="${xx(v)}" y="${H-12}" text-anchor="middle">${v}Y</text>`;}
 else{for(let i=0;i<(mobile?4:7);i++){const v=xmin+(xmax-xmin)*i/(mobile?3:6),day=new Date(v).toISOString().slice(0,7);svg+=`<text x="${L+(W-L-R)*i/(mobile?3:6)}" y="${H-12}" text-anchor="${i===0?'start':i===(mobile?3:6)?'end':'middle'}">${day}</text>`;}
 if(X.events)events.filter(ev=>xval(ev.date)>=xmin&&xval(ev.date)<=xmax).forEach((ev,i)=>{const x=xx(ev.date);svg+=`<line class="event-line" x1="${x}" x2="${x}" y1="${T-6}" y2="${H-B}"/><text x="${Math.max(L+4,Math.min(W-90,x+4))}" y="${15+(i%2)*14*scale}">${e(ev.label)}</text>`;});}
 lines.forEach((s,i)=>{let seg=[],segments=[],prev=null;for(const p of s.points){if(!C.finite(p[1])){if(seg.length)segments.push(seg);seg=[];prev=null;continue;}if(!curve&&prev&&xval(p[0])-xval(prev)>62*86400000){if(seg.length)segments.push(seg);seg=[];}seg.push([xx(p[0]),yy(p[1])]);prev=p[0];}if(seg.length)segments.push(seg);svg+=segments.map(a=>`<polyline points="${a.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2.7" stroke-linejoin="round"/>`).join('');if(curve)svg+=s.points.filter(p=>C.finite(p[1])).map(p=>`<circle cx="${xx(p[0])}" cy="${yy(p[1])}" r="3.5" fill="${colors[i]}"><title>${e(s.name)} · ${p[0]}Y · ${n(p[1])}%</title></circle>`).join('');else{const p=s.points.filter(p=>C.finite(p[1])).at(-1);if(p)svg+=`<circle cx="${xx(p[0])}" cy="${yy(p[1])}" r="4" fill="${colors[i]}"/>`;}});
 if(scenario){const endx=xx(scenario.end[0]),startx=xx(scenario.start[0]);svg+=`<rect x="${startx}" y="${T}" width="${endx-startx}" height="${H-T-B}" fill="#d6e8f4" opacity=".32"/><line x1="${startx}" x2="${endx}" y1="${yy(scenario.start[1])}" y2="${yy(scenario.end[1])}" stroke="#a74478" stroke-width="3" stroke-dasharray="7 5"/><text x="${W-R}" y="${T-13}" text-anchor="end" fill="#9a3c73">${e(t('Hypothetical path'))}</text>`;}
 return svg+'</svg>'+`<div class="legend">${lines.map((s,i)=>`<span><i style="background:${colors[i]}"></i>${e(s.name)}</span>`).join('')}${scenario?`<span><i style="background:#a74478"></i>${e(t('Hypothetical path'))}</span>`:''}</div>`;
}
function timeData(){const fx=X.historyTab==='fx',a=X.history.series.find(s=>s.id===(fx?X.fxA:X.historyA));let b=X.history.series.find(s=>s.id===(fx?X.fxB:X.historyB));if(!a)return{a:null,lines:[]};if(b?.family!==a.family&&!(b?.family!=='fx'&&a.family!=='fx'))b=null;
 const cut=s=>s.points.filter(p=>p[0]>=X.start&&p[0]<=X.end);let sets=[a,...(b&&b.id!==a.id?[b]:[])].map(s=>({name:s.id,points:cut(s)}));
 if(fx&&X.fxMode==='index'){const common=sets.length>1?sets[0].points.filter(p=>sets[1].points.some(q=>q[0]===p[0]))[0]?.[0]:sets[0].points[0]?.[0];sets=sets.map(s=>{const base=s.points.find(p=>p[0]===common)?.[1];return{...s,points:base?s.points.filter(p=>p[0]>=common).map(p=>[p[0],p[1]/base*100]):[]};});}
 return{a,b,lines:sets};
}
function historyView(){const intro=head('History & context','Historical yields & FX',t('Explore monthly history, compare two dates across the curve, and keep hypothetical paths separate from observations.','浏览月度历史，比较两个日期的期限曲线，并将假设路径与历史观测值分开。','瀏覽月度歷史，比較兩個日期的期限曲線，並將假設路徑與歷史觀測值分開。'));if(!X.history)return intro+loading('history');return intro+notice(e(t('Supplied workbook observations end in August 2026. Monthly aggregation methodology has not been independently verified.','用户提供的工作簿数据截至 2026 年 8 月；月度汇总方法未独立核实。','使用者提供的活頁簿數據截至 2026 年 8 月；月度彙總方法未獨立核實。')))+subnav([['yield','Yield history'],['fx','FX history'],['curves','Historical curves']],X.historyTab,'historyTab')+(X.historyTab==='curves'?curveView():timeView());}
function timeView(){const fx=X.historyTab==='fx',pool=X.history.series.filter(s=>fx?s.family==='fx':s.family!=='fx'),{a,b,lines}=timeData();if(!a)return loading('history');const points=lines[0].points,summary=C.seriesStats(points),rawPoints=a.points.filter(p=>p[0]>=X.start&&p[0]<=X.end),raw=C.seriesStats(rawPoints);let sc=null;
 if(X.scenario!==0&&points.length&&X.end>=a.points.at(-1)[0]){const last=points.at(-1);sc={start:last,end:[addMonths(last[0],X.horizon),fx?last[1]*(1+X.scenario/100):last[1]+X.scenario/100]};}
 const statsData=raw?[[n(raw.last[1],fx?4:2)+(fx?'':'%'),'Latest observation'],[raw.count,'Observations'],[n(raw.min,fx?4:2)+' – '+n(raw.max,fx?4:2),'Range'],[fx?n(C.fxChange(raw.first[1],raw.last[1]))+'%':n(raw.change*100,0)+'bp','Change']]:[];
 const rows=Array.from(new Set(lines.flatMap(s=>s.points.map(p=>p[0])))).sort().reverse();
 return`<div class="tool-controls">${label('Series',select('history-series',pool.map(s=>[s.id,s.id]),fx?X.fxA:X.historyA))}${label('Compare series',select('history-compare',[['','None'],...pool.map(s=>[s.id,s.id])],fx?X.fxB:X.historyB))}${label('Period',select('history-period',[['all','All history'],['5','5 years'],['10','10 years'],['20','20 years'],['custom','Custom dates']],'custom'))}${label('From',input('history-start',X.start,'date'))}${label('To',input('history-end',X.end,'date'))}${fx?label('Display',select('fx-mode',[['level','Level'],['index','Rebased to 100']],X.fxMode)):''}</div>${fx&&lines.length>1&&X.fxMode==='level'?notice(e(t('The pairs may use different base currencies. Their absolute levels are not directly comparable; rebasing compares percentage moves.','不同货币对的基础货币可能不同，绝对汇率不可直接比较；可改用起点 100 比较百分比变化。','不同貨幣對的基礎貨幣可能不同，絕對匯率不可直接比較；可改用起點 100 比較百分比變化。'))):''}${stats(statsData)}<div class="chart-panel"><div class="eyebrow">${e(t('Monthly observations'))} · ${raw?e(d(raw.first[0])+' – '+d(raw.last[0])):'—'}</div><h3>${e(a.id)} · ${e(t(fx?'FX history':'Yield history'))}</h3><p class="caption">${e(fx?(X.fxMode==='index'?t('Common first observation = 100.','共同起始观测值 = 100。','共同起始觀測值 = 100。'):a.id.split('/')[1]+' per '+a.id.split('/')[0]):t('Annual yield in percentage points.','年化收益率，单位为百分点。','年化收益率，單位為百分點。'))}</p>${lineChart(lines,{title:a.id+' '+t('Historical yields & FX'),unit:fx?(X.fxMode==='index'?'100':'FX'):'%',scenario:sc})}<p class="chart-description">${e(t('Gaps are not filled. Event markers provide context, not proof of causation.','缺失值不填补；事件标记提供背景，不代表因果证明。','缺失值不填補；事件標記提供背景，不代表因果證明。'))}</p><label class="field inline"><input id="history-events" type="checkbox" ${X.events?'checked':''}>${e(t('Show event markers'))}</label></div><div class="card"><h3>${e(t('Hypothetical path'))}</h3><p class="v3-caption">${e(t('Anchored to the last supplied observation, not today. A straight assumed path is not a forecast or forward curve. Shown only when the selected range includes the latest observation.','假设路径从最后一个来源观测值开始，不是从今天开始；直线假设不是预测或远期曲线。只有所选区间包含最新观测值时才显示。','假設路徑從最後一個來源觀測值開始，並非從今天開始；直線假設不是預測或遠期曲線。只有所選區間包含最新觀測值時才顯示。'))}</p><div class="tool-controls">${label(fx?'Scenario FX change (%)':'Scenario yield change (bp)',input('history-scenario',X.scenario,'number',fx?'min="-80" max="200" step="1"':'min="-500" max="500" step="25"'))}${label('Scenario horizon (months)',select('history-horizon',[[6,'6'],[12,'12'],[24,'24'],[36,'36']].map(([v,k])=>[String(v),k]),String(X.horizon)))}</div></div><details class="card section"><summary>${e(t('Read the data'))}</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>${e(t('Date'))}</th>${lines.map(s=>`<th>${e(s.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(day=>`<tr><td>${e(day.slice(0,7))}</td>${lines.map(s=>`<td>${n(s.points.find(p=>p[0]===day)?.[1],fx?4:2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>${historySource(a)}${a.derived?notice(e(t('CHF/SGD is a workbook-derived cross: USD/SGD divided by USD/CHF. It is not a direct Fed quote.','CHF/SGD 是工作簿推导的交叉汇率：USD/SGD ÷ USD/CHF，并非美联储直接报价。','CHF/SGD 是活頁簿推導的交叉匯率：USD/SGD ÷ USD/CHF，並非聯準會直接報價。'))):''}${eventsSource()}`;
}
function historySource(s){return`<p class="source-line">${e(X.history.source_file)} · ${e(s?.source_sheet||'')} · ${e(t('Supplied snapshot'))}. ${e(t('Source dates are observation periods; importing does not make them current.','来源日期代表观测期间，导入不代表数据变成最新。','來源日期代表觀測期間，匯入不代表數據變成最新。'))}</p>`;}
function eventsSource(){return`<details class="section"><summary>${e(t('Historical event sources','历史事件来源','歷史事件來源'))}</summary><div class="links">${events.map(ev=>link(ev.url,ev.label+' · '+ev.date)).join('')}</div><p class="v3-caption">${e(t('These markers identify policy announcement dates, not exact monthly market turning points.','标记对应政策宣布日期，不代表月度市场转折点。','標記對應政策宣布日期，不代表月度市場轉折點。'))}</p></details>`;}
function curveView(){const families=X.curveFamily==='both'?['ust','sgs']:[X.curveFamily],dates=[...new Set(X.history.series.filter(s=>families.includes(s.family)).flatMap(s=>s.points.map(p=>p[0])))].sort().reverse();const curves=families.flatMap(f=>[X.curveA,X.curveB].map(day=>({family:f,day,name:(f==='ust'?'USD UST':'SGD SGS')+' · '+day.slice(0,7),curve:C.curve(X.history,f,day)}))),lines=curves.map(c=>({name:c.name,points:c.curve.map(x=>[x.years,x.value])})),a=curves[0]?.curve||[],b=curves[1]?.curve||[],delta=C.curveDelta(a,b),missing=curves.reduce((s,c)=>s+c.curve.filter(p=>p.value===null).length,0);
 return`<div class="tool-controls">${label('Curve family',select('curve-family',[['ust','U.S. Treasury'],['sgs','Singapore SGS'],['both','USD UST + SGD SGS']],X.curveFamily))}${label('Date A',select('curve-a',dates.map(v=>[v,v.slice(0,7)]),X.curveA))}${label('Date B',select('curve-b',dates.map(v=>[v,v.slice(0,7)]),X.curveB))}</div><div class="chart-panel"><div class="eyebrow">${e(t('Compare historical curves'))}</div><h3>${e(t('Two dates. The full maturity structure.','两个日期，完整期限结构。','兩個日期，完整期限結構。'))}</h3><p class="caption">${e(t('X: years to maturity · Y: annual yield (%)','横轴：期限（年）· 纵轴：年化收益率（%）','橫軸：期限（年）· 縱軸：年化收益率（%）'))}</p>${lineChart(lines,{title:t('Compare historical curves'),unit:'%',curve:true})}<p class="chart-description">${e(t('Observed benchmark tenors are connected for readability. This is not a bootstrapped zero curve or an executable security-yield curve.','为便于阅读，图中连接已观测的基准期限；这不是引导计算的零息曲线或可成交证券收益率曲线。','為便於閱讀，圖中連接已觀測的基準期限；這不是引導計算的零息曲線或可成交證券收益率曲線。'))}</p></div>${X.curveFamily==='both'?notice(e(t('USD and SGD curves carry different currency and policy exposures. Their yield difference is not an FX-hedged return.','美元与新元曲线具有不同的货币及政策风险，收益率差并非汇率对冲后的回报。','美元與新元曲線具有不同的貨幣及政策風險，收益率差並非匯率對沖後的回報。'))):''}${missing?notice(missing+' '+e(t('Periods missing'))+' · '+e(t('Not interpolated'))):''}<div class="comparison-delta">${delta.filter(x=>['2Y','5Y','10Y','30Y'].includes(x.label)).map(x=>`<div>${e(x.label)} · A − B<b>${x.bp===null?'—':(x.bp>0?'+':'')+n(x.bp,0)+'bp'}</b></div>`).join('')}</div><div class="card"><h3>${e(t('Read the data'))}</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>${e(t('Tenor'))}</th>${curves.map(c=>`<th>${e(c.name)}</th>`).join('')}<th>${e(t('A − B (bp)'))}${X.curveFamily==='both'?' · USD':''}</th></tr></thead><tbody>${Array.from(new Set(curves.flatMap(c=>c.curve.map(p=>p.label)))).sort((a,b)=>C.tenor(a)-C.tenor(b)).map(l=>`<tr><td>${e(l)}</td>${curves.map(c=>`<td>${C.finite(c.curve.find(x=>x.label===l)?.value)?n(c.curve.find(x=>x.label===l).value)+'%':'—'}</td>`).join('')}<td>${n(delta.find(x=>x.label===l)?.bp,0)}</td></tr>`).join('')}</tbody></table></div></div>${historySource(X.history.series.find(s=>s.family===families[0]))}`;
}

function ustRows(){return C.ustFilter(X.ust.rows,{q:X.ustQ,min:X.ustMin,max:X.ustMax,coupon:X.ustCoupon,yield:X.ustYield,nonnegative:X.ustPositive},X.asof).sort((a,b)=>X.ustSort==='yield'?b.reportedYieldPct-a.reportedYieldPct:X.ustSort==='coupon'?b.couponPct-a.couponPct:a.maturity.localeCompare(b.maturity)||a.couponPct-b.couponPct);}
function quote(r,side){if(!X.ustConvention)return null;return E.parseQuote(r[side==='bid'?'rawBid':'rawAsk'],X.ustConvention);}
function quoteText(r){const a=quote(r,'bid'),b=quote(r,'ask');if(!a||!b)return e(r.rawBid??'—')+' / '+e(r.rawAsk??'—');return(a.ok?n(a.value,5):'⚠')+' / '+(b.ok?n(b.value,5):'⚠');}
function scatter(rows){const scale=Number(document.documentElement.style.getPropertyValue('--text-scale'))||1,W=matchMedia('(max-width:760px)').matches?400:900,H=document.documentElement.dataset.displayCharts==='large'?390:280,L=Math.ceil(45*scale),R=18,T=Math.ceil(28*scale),B=Math.ceil(40*scale),points=rows.map(r=>({r,x:C.yearsTo(r.maturity,X.asof),y:r.reportedYieldPct})).filter(p=>C.finite(p.y));if(!points.length)return'<div class="empty">'+e(t('No matches'))+'</div>';let xmax=Math.max(...points.map(p=>p.x)),ymin=Math.min(...points.map(p=>p.y)),ymax=Math.max(...points.map(p=>p.y));if(ymin===ymax)ymax+=.1;const span=ymax-ymin;ymin-=span*.15;ymax+=span*.15;xmax=Math.max(1,xmax);const xx=x=>L+x/xmax*(W-L-R),yy=y=>H-B-(y-ymin)/(ymax-ymin)*(H-T-B);let svg=`<svg class="v3-chart" role="img" viewBox="0 0 ${W} ${H}" aria-label="${e(t('Reported-yield scatter'))}"><title>${e(t('Reported-yield scatter'))} · ${rows.length} observations</title><desc>${e(t('Use the security cards below for source terms and comparison.','请通过下方证券卡查看来源条款及比较。','請透過下方證券卡檢視來源條款及比較。'))}</desc>`;for(let i=0;i<5;i++){const y=ymin+(ymax-ymin)*i/4;svg+=`<line class="axis-line" x1="${L}" x2="${W-R}" y1="${yy(y)}" y2="${yy(y)}"/><text x="${L-6}" y="${yy(y)+4}" text-anchor="end">${n(y)}%</text>`;}for(let i=0;i<5;i++){const v=xmax*i/4;svg+=`<text x="${xx(v)}" y="${H-14}" text-anchor="${i===0?'start':i===4?'end':'middle'}">${n(v,1)}Y</text>`;}svg+=points.map(p=>`<circle cx="${xx(p.x)}" cy="${yy(p.y)}" r="${X.ustCompare.includes(p.r.id)?5:3}" fill="${X.ustCompare.includes(p.r.id)?'#a14b80':p.y<0?'#c37536':'#177e93'}" opacity=".7"><title>${e(p.r.maturity)} · coupon ${p.r.couponPct}% · reported ${p.r.reportedYieldPct}%</title></circle>`).join('');return svg+'</svg>';}
function ustCard(r){const chosen=X.ustCompare.includes(r.id),a=quote(r,'bid'),b=quote(r,'ask'),bad=a&&b&&(!a.ok||!b.ok||(a.value>b.value));return`<article class="ust-card"><div class="eyebrow">${e(d(r.maturity))}</div><div class="coupon">${n(r.couponPct,3)}%</div><h3>${e(t('U.S. Treasury'))}</h3><div class="metric-grid"><div><span>${e(t('Reported yield'))}</span><strong>${n(r.reportedYieldPct,3)}%</strong></div><div><span>${e(t('Years remaining'))}</span><strong>${n(C.yearsTo(r.maturity,X.asof),2)}</strong></div></div><div class="v3-caption">${e(t(X.ustConvention?'Interpreted bid / ask':'Raw bid / ask'))}</div><div class="cell-number">${quoteText(r)}</div>${bad?`<div class="invalid v3-caption">${e(t('Quote interpretation needs review.','报价换算需核对。','報價換算需核對。'))}</div>`:''}<p class="v3-subtle">${e(t('Identity requires review'))} · row ${r.sourceRow}</p>${button(chosen?'Remove from compare':'Add to compare',`data-tool="compare" data-id="${e(r.id)}" aria-pressed="${chosen}"`)}<button class="details-link" data-tool="ust-detail" data-id="${e(r.id)}">${e(t('View source details'))} ↗</button></article>`;}
function ustComparison(){if(!X.ustCompare.length)return'';const selected=X.ustCompare.map(id=>X.ust.rows.find(r=>r.id===id)).filter(Boolean);return`<section class="section"><div class="section-title"><h2>${e(t('Compare selected USTs'))}</h2>${button('Clear selection','data-tool="compare-clear"','button ghost')}</div><div class="ust-comparison">${selected.map(r=>`<article><h3>${e(r.maturity)}</h3><div class="metric-grid"><div><span>${e(t('Coupon'))}</span><strong>${n(r.couponPct,3)}%</strong></div><div><span>${e(t('Reported yield'))}</span><strong>${n(r.reportedYieldPct,3)}%</strong></div><div><span>${e(t('Raw bid / ask'))}</span><strong style="font-size:calc(14px * var(--text-scale,1))">${e(r.rawBid)} / ${e(r.rawAsk)}</strong></div><div><span>${e(t('Years remaining'))}</span><strong>${n(C.yearsTo(r.maturity,X.asof))}</strong></div></div>${button('Remove',`data-tool="compare" data-id="${e(r.id)}"`,'button ghost')}</article>`).join('')}</div><p class="v3-caption">${e(t('Each column is a separate candidate, not an allocation or combined portfolio. Reported yield alone does not determine the best fit.','每列代表单独候选债券，不是资产配置或合并投资组合。来源收益率不能单独决定哪只最合适。','每欄代表單獨候選債券，並非資產配置或合併投資組合。來源收益率不能單獨決定哪一檔最合適。'))}</p></section>`;}
function ustView(){const intro=head('UST bond selection','Daily pricing & observed curve',t('Compare individual Treasury observations by maturity, coupon, source price and reported yield.','按到期日、票息、来源价格及来源收益率比较美国国债。','按到期日、票息、來源價格及來源收益率比較美國國債。'));if(!X.ust)return intro+loading('ust');const rows=ustRows(),show=rows.slice(0,36);return intro+notice(e(t('All supplied observations require review. Market quote time, security identity and price convention are unconfirmed. The workbook date is not a quote timestamp.','所有来源观测值均待核对，市场报价时间、证券身份及价格格式尚未确认。工作簿日期不等于报价时间。','所有來源觀測值均待核對，市場報價時間、證券身分及價格格式尚未確認。活頁簿日期不等於報價時間。')))+`<div id="ust-stats">${stats([[X.ust.rows.length,'Source rows'],[rows.length,'Matching candidates'],[X.ust.quote_date?d(X.ust.quote_date):'—','Quote date'],[X.ustCompare.length+'/4','Selected']])}</div>`+`<div class="tools-row">${button('Upload a refreshed snapshot','data-tool="ust-upload"')}${button('Compare historical curves','data-tool="ust-history"','button ghost')}</div><div class="tool-controls">${label('Research reference date',input('ust-asof',X.asof,'date'))}${label('Price convention',select('ust-convention',[['','Unconfirmed / raw only'],['treasury32','Treasury points & 32nds'],['decimal','Decimal per 100']],X.ustConvention))}${label('Sort by',select('ust-sort',[['maturity','Maturity'],['yield','Reported yield'],['coupon','Coupon']],X.ustSort))}</div><div class="tool-intro">${e(t('Changing a price convention previews an interpretation only. It does not verify the quote or recalculate the supplied yield.','选择价格格式仅用于预览换算，不代表报价已核实，也不会重新计算来源收益率。','選擇價格格式僅用於預覽換算，不代表報價已核實，也不會重新計算來源收益率。'))}</div><label class="sr-only" for="ust-search">${e(t('Search maturity, coupon or source identifier'))}</label><input class="search" id="ust-search" value="${e(X.ustQ)}" placeholder="${e(t('Search maturity, coupon or source identifier'))}"><details class="advanced-filters"><summary>${e(t('More filters'))}</summary><div class="tool-controls">${label('Minimum years',input('ust-min',X.ustMin,'number','min="0" max="100" step="0.5"'))}${label('Maximum years',input('ust-max',X.ustMax,'number','min="0" max="100" step="0.5"'))}${label('Minimum coupon (%)',input('ust-coupon',X.ustCoupon,'number','min="0" max="100" step="0.125"'))}${label('Minimum reported yield (%)',input('ust-yield',X.ustYield,'number','min="-25" max="100" step="0.1"'))}</div><label class="field inline"><input id="ust-positive" type="checkbox" ${X.ustPositive?'checked':''}>${e(t('Exclude negative reported yields'))}</label></details><div id="ust-results">${ustResults(rows)}</div><section class="card section"><h3>${e(t('How to use this desk','如何使用此研究台','如何使用此研究台'))}</h3><div class="glossary"><div><b>${e(t('Coupon'))}</b><p>${e(t('Annual stated coupon divided by face value. It is different from yield and cash return on purchase cost.','年度约定票息除以面值；它不同于收益率或按购买成本计算的现金回报。','年度約定票息除以面值；它不同於收益率或按購買成本計算的現金回報。'))}</p></div><div><b>${e(t('Reported yield'))}</b><p>${e(t('As supplied in the WSJ file. Yield convention and quotation time still require confirmation.','按 WSJ 文件原样显示，收益率口径及报价时间仍需确认。','按 WSJ 檔案原樣顯示，收益率口徑及報價時間仍需確認。'))}</p></div><div><b>${e(t('Price / maturity map'))}</b><p>${e(t('A security-yield scatter describes individual bonds. It is distinct from a constant-maturity benchmark curve.','证券收益率散点图描述各只债券，与固定期限基准收益率曲线不同。','證券收益率散點圖描述各檔債券，與固定期限基準收益率曲線不同。'))}</p></div><div><b>${e(t('Source AR'))}</b><p>${e(t('No source AR has been attached to these unverified WSJ identities. The master remains a separate source.','不会将来源 AR 附加到未经核实的 WSJ 证券身份，证券主档保持独立来源。','不會將來源 AR 附加到未經核實的 WSJ 證券身分，證券主檔保持獨立來源。'))}</p></div></div></section><p class="source-line">${e(X.ust.source_file)} · WSJ!A:F · ${e(t('Unknown quote time'))}. ${e(t('No modeled STRIPS or spreadsheet-derived yields are treated as observed quotes.','不将模型 STRIPS 或工作表推导收益率视为观测报价。','不將模型 STRIPS 或工作表推導收益率視為觀測報價。'))}</p>`;}
function ustResults(rows){return`${ustComparison()}<div class="chart-panel"><h3>${e(t('Reported-yield scatter'))}</h3><p class="caption">${e(t('X: years remaining at research date · Y: supplied reported yield (%)','横轴：研究参考日剩余年期 · 纵轴：来源收益率（%）','橫軸：研究參考日剩餘年期 · 縱軸：來源收益率（%）'))}</p>${scatter(rows)}<p class="chart-description">${e(t('Observed points are not fitted into a par, zero or forward curve. Orange flags a negative source yield.','观测点没有拟合为平价、零息或远期曲线；橙色表示来源负收益率。','觀測點並未擬合為平價、零息或遠期曲線；橙色表示來源負收益率。'))}</p></div><div class="tools-row"><span class="count-line">${rows.length} ${e(t('matching candidates','只符合的候选债券','檔符合的候選債券'))} · ${e(t('showing first 36','显示前 36 条','顯示前 36 筆'))}</span>${button('Clear filters','data-tool="ust-clear"','button ghost')}</div><div class="ust-card-grid">${rows.slice(0,36).map(ustCard).join('')||`<div class="empty">${e(t('No matches'))}</div>`}</div>`;}
function ustDetail(id){const r=X.ust.rows.find(r=>r.id===id);if(!r)return;showDialog('UST · '+r.maturity,notice(e(t('Identity requires review'))+' · '+e(t('Unknown quote time')))+`<dl class="raw-grid">${[['Maturity',r.maturity],['Coupon',r.couponPct+'%'],['Raw bid / ask',(r.rawBid??'—')+' / '+(r.rawAsk??'—')],['Reported yield',r.reportedYieldPct+'%'],['Source row',r.sourceRow],['Pasted source ISIN · unverified',r.ignoredRawIsin||'—']].map(([k,v])=>`<div><dt>${e(t(k))}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><h3>${e(t('Exact source numeric text','精确来源数值文本','精確來源數值文字'))}</h3><pre style="white-space:pre-wrap;font-size:calc(12px * var(--text-scale,1))">${e(JSON.stringify(r.sourceNumericText||{},null,2))}</pre><p>${e(t('Pasted ISINs have not been adopted as verified identities. Mismatched source identifiers must be reconciled before prices or policy fields are joined.','粘贴的 ISIN 未被采纳为已核实身份，须先核对不匹配编号，再连接价格及政策字段。','貼上的 ISIN 並未採納為已核實身分，須先核對不符編號，再連接價格及政策欄位。'))}</p>${button(X.ustCompare.includes(id)?'Remove from compare':'Add to compare',`data-tool="compare" data-id="${e(id)}"`)}`);}
function feedsView(){return head('Data & refresh','Upload a refreshed snapshot',t('Review changes before applying. Your uploads are read locally and are not sent to a server.','先检查变更再应用。上传文件只在浏览器本地读取，不发送到服务器。','先檢查變更再套用。上傳檔案僅在瀏覽器本機讀取，不會傳送到伺服器。'))+workspaceNote()+`<div class="grid"><article class="card"><h3>${e(t('Choose data type'))}</h3><label class="field">${e(t('Choose data type'))}${select('feed-type',[['master','Master list'],['history','Historical yields / FX'],['ust','UST daily file']],X.feedType)}</label><div class="file-drop"><b>${e(t('Preview import'))}</b><p class="v3-caption">${e(t('Master: XLSX, Security Library HTML, JSON or CSV. History: supplied-layout XLSX or normalized JSON. UST: WSJ XLSX, CSV or normalized JSON. Maximum 20 MiB.','主档支持 XLSX、Security Library HTML、JSON 或 CSV；历史支持指定格式 XLSX 或标准 JSON；国债支持 WSJ XLSX、CSV 或标准 JSON，最大 20 MiB。','主檔支援 XLSX、Security Library HTML、JSON 或 CSV；歷史支援指定格式 XLSX 或標準 JSON；國債支援 WSJ XLSX、CSV 或標準 JSON，最大 20 MiB。'))}</p><label for="data-file">${e(t('Choose a local file','选择本地文件','選擇本機檔案'))}</label><input id="data-file" type="file" accept=".xlsx,.html,.json,.csv,.tsv"></div><div id="import-message" class="status-msg" role="status"></div><div id="import-preview"></div><div class="links">${button('Rollback previous snapshot','data-tool="rollback"','button ghost')}${button('Download backup','data-tool="backup"','button ghost')}</div><p class="v3-caption">${e(t('Local snapshots apply to this browser. Publishing a shared refresh is a separate owner action. The original supplied files remain unchanged.','本地快照仅应用于当前浏览器；发布共享刷新是另外的所有者操作，原始文件保持不变。','本機快照僅套用於目前瀏覽器；發布共享重新整理屬於另一項擁有者操作，原始檔案保持不變。'))}</p></article><article class="card"><h3>${e(t('Future connections'))}</h3>${[['1','MAS SGS yields','Historical benchmark tenors; source date, frequency and revision history.','SGS 基准期限收益率，记录来源日期、频率及修订历史。','SGS 基準期限收益率，記錄來源日期、頻率及修訂歷史。'],['2','Treasury yields','Benchmark yield curve history; distinct from individual WSJ bond yields.','基准收益率曲线历史，独立于 WSJ 各只债券收益率。','基準收益率曲線歷史，獨立於 WSJ 各檔債券收益率。'],['3','Federal Reserve FX','Explicit base/quote direction and observation date. Derived cross rates stay labelled.','明确基础及计价货币方向与观测日期，推导交叉汇率保持标记。','明確基礎及計價貨幣方向與觀測日期，推導交叉匯率保持標記。'],['4','WSJ UST daily pricing','Daily instrument observations with quote time, notation and identity review.','每日证券观测值，含报价时间、格式与身份核对。','每日證券觀測值，含報價時間、格式與身分核對。']].map(([no,name,en,sc,tc])=>`<div class="feed-step"><span>${no}</span><div><h4>${e(name)}</h4><p>${e(t(en,sc,tc))}</p><span class="feed-state">${e(t('Prepared, not connected'))}</span></div></div>`).join('')}</article></div><article class="card section"><h3>${e(t('Automatic website feed'))}</h3><p>${e(t('The existing Reuters headline and short Treasury snapshot refresh continues on GitHub. The new full historical workbook and WSJ price adapters are prepared for a later connection; they are not automatically refreshed in this release.','现有路透新闻及简版美国国债快照继续通过 GitHub 更新。新的完整历史与 WSJ 价格接口已预留，待以后连接；本版本不会自动刷新这些数据。','現有路透新聞及簡版美國國債快照繼續透過 GitHub 更新。新的完整歷史及 WSJ 價格介面已預留，待日後連接；本版本不會自動重新整理這些數據。'))}</p><div class="links">${button('Historical yields & FX','data-view="history"')}${button('UST selection desk','data-view="ust"')}${link('v2.html','Version 2 fallback')}</div></article>`;}

async function fileHash(bytes){const a=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(a)).map(b=>b.toString(16).padStart(2,'0')).join('');}
function decodeXml(s){return String(s).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16))).replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(Number(n))).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');}
function attr(s,k){return new RegExp('(?:^|\\s)'+k.replace(':','\\:')+'=["\']([^"\']*)["\']').exec(s)?.[1]||'';}
function workbookSheets(bytes){const z=I._test.unzip(new Uint8Array(bytes)),wb=z.read('xl/workbook.xml');if(!wb)throw Error('Workbook metadata is missing.');const rels=z.read('xl/_rels/workbook.xml.rels')||'',rel=new Map([...rels.matchAll(/<Relationship\b([^>]+)\/?\s*>/g)].map(m=>[attr(m[1],'Id'),attr(m[1],'Target')])),sharedXml=z.read('xl/sharedStrings.xml')||'',shared=[...sharedXml.matchAll(/<(?:\w+:)?si\b[^>]*>([\s\S]*?)<\/(?:\w+:)?si>/g)].map(m=>[...m[1].matchAll(/<(?:\w+:)?t\b[^>]*>([\s\S]*?)<\/(?:\w+:)?t>/g)].map(x=>decodeXml(x[1])).join(''));
 const out={};for(const m of wb.matchAll(/<(?:\w+:)?sheet\b([^>]+)\/?\s*>/g)){const name=decodeXml(attr(m[1],'name'));if(!['ACE','ACE snapshot','Master','Yields_FX_API','4 MAS SGS Static'].includes(name))continue;let path=rel.get(attr(m[1],'r:id'))||'';path=path.replace(/^\//,'');if(!path.startsWith('xl/'))path='xl/'+path;const xml=z.read(path);if(!xml)continue;const rows=[];for(const rr of xml.matchAll(/<(?:\w+:)?row\b(?![^>]*\/>)([^>]*)>([\s\S]*?)<\/(?:\w+:)?row>/g)){const values=[];for(const cc of rr[2].matchAll(/<(?:\w+:)?c\b(?![^>]*\/>)([^>]*)>([\s\S]*?)<\/(?:\w+:)?c>/g)){const address=attr(cc[1],'r'),letters=/^([A-Z]+)/.exec(address)?.[1];if(!letters)continue;let col=0;for(const c of letters)col=col*26+c.charCodeAt(0)-64;if(col>100)throw Error('Worksheet column limit exceeded.');let v=/<(?:\w+:)?v\b[^>]*>([\s\S]*?)<\/(?:\w+:)?v>/.exec(cc[2])?.[1]??null;const typ=attr(cc[1],'t');if(typ==='s')v=shared[Number(v)]??null;else if(typ==='inlineStr')v=[...cc[2].matchAll(/<(?:\w+:)?t\b[^>]*>([\s\S]*?)<\/(?:\w+:)?t>/g)].map(x=>decodeXml(x[1])).join('');else if(v!==null)v=decodeXml(v);values[col-1]=v;}rows.push({row:Number(attr(rr[1],'r')),values});if(rows.length>15020)throw Error('Worksheet row limit exceeded.');}out[name]=rows;}
 return{ sheets:out,date1904:/date1904=["'](?:1|true)["']/.test(wb)};
}
function fromMasterTable(rows,name,hash,sheet='Imported'){const headerIndex=rows.findIndex(r=>r.values.includes('ISIN')&&r.values.includes('Security Name'));if(headerIndex<0)throw Error('The ISIN / Security Name header row is missing.');const headers=rows[headerIndex].values,map=Object.fromEntries(C.fields.map(f=>[f,headers.indexOf(f)]));if(['ISIN','Security Name','Security Currency','Last Price','Short Description'].some(k=>map[k]<0))throw Error('Required master columns are missing.');const snapshotId='upload-'+hash.slice(0,20),records=rows.slice(headerIndex+1).filter(r=>r.values.some(v=>v!==null&&v!==undefined&&v!=='')).map(r=>{const raw=Object.fromEntries(C.fields.map(f=>[f,map[f]<0||r.values[map[f]]===undefined?null:r.values[map[f]]]));return C.record(raw,r.row,snapshotId);});return C.validateMaster({schemaVersion:'1.0.0',snapshot:{id:snapshotId,sourceFile:name,sheet,recordCount:records.length,filenameDate:null,observationTime:null,policyEffectiveTime:null,sourceSha256:hash},rawFields:C.fields,records});}
function excelDay(v,date1904){if(C.validDate(v))return v;const num=C.numeric(v);if(num===null||num<1||num>100000)return null;return new Date(Date.UTC(date1904?1904:1899,date1904?0:11,date1904?1:30)+Math.floor(num)*86400000).toISOString().slice(0,10);}
function fromHistoryWorkbook(wb,name,hash){const series=[];for(const [sheet,rows] of Object.entries(wb.sheets)){if(!['Yields_FX_API','4 MAS SGS Static'].includes(sheet))continue;const headers=rows[0]?.values||[];headers.forEach((h,col)=>{if(col===0||typeof h!=='string'||!(/^(UST |SGD |[A-Z]{3}\/[A-Z]{3}$)/.test(h)))return;if(sheet==='Yields_FX_API'&&h.startsWith('SGD '))return;const family=h.includes('/')?'fx':h.startsWith('SGD ')?'sgs':'ust',points=[];for(const row of rows.slice(1)){const day=excelDay(row.values[0],wb.date1904),v=C.numeric(row.values[col]);if(day&&v!==null)points.push([day,v]);}if(points.length)series.push({id:h,family,unit:family==='fx'?'quote per base':'% p.a.',source_sheet:sheet,frequency:'monthly',derived:h==='CHF/SGD',points:points.sort((a,b)=>a[0].localeCompare(b[0]))});});}return C.validateHistory({schemaVersion:1,id:'history-upload-'+hash.slice(0,16),source_file:name,sha256:hash,status:'supplied_snapshot',verified_provider_refresh:false,frequency:'monthly',series});}
function normalizeUST(result,name,hash){if(!result.ok)throw Error(result.errors?.join(' ')||'UST import failed.');const s=result.snapshot,keys=['id','name','currency','instrumentType','maturity','couponPct','frequency','rawBid','rawAsk','reportedYieldPct','sourceRow','sourceNumericText','ignoredRawIsin'];return C.validateUST({schemaVersion:1,id:s.id||'ust-upload-'+hash.slice(0,16),source_file:name,source_sha256:hash,imported_at:new Date().toISOString(),quote_date:s.quoteDate||null,status:'review_required',rows:s.rows.map(r=>Object.fromEntries(keys.map(k=>[k,r[k]??null])))});}
async function parseImport(file,type){if(!file||file.size>20*1024*1024)throw Error('Choose a file no larger than 20 MiB.');const bytes=await file.arrayBuffer(),hash=await fileHash(bytes),name=file.name.toLowerCase();
 if(name.endsWith('.json')){const json=JSON.parse(new TextDecoder().decode(bytes));return validate(type,json);}
 if(type==='ust')return normalizeUST(await I.parseFile(file),file.name,hash);
 if(name.endsWith('.xlsx')){const wb=workbookSheets(bytes);if(type==='history')return fromHistoryWorkbook(wb,file.name,hash);const sheet=['ACE','ACE snapshot','Master'].find(k=>wb.sheets[k]);if(!sheet)throw Error('Use a workbook with ACE, ACE snapshot or Master sheet.');return fromMasterTable(wb.sheets[sheet],file.name,hash,sheet);}
 const text=new TextDecoder().decode(bytes);if(type==='master'&&name.endsWith('.html')){const doc=new DOMParser().parseFromString(text,'text/html'),source=doc.getElementById('security-library-data');if(!source)throw Error('Security Library data block is missing.');return C.validateMaster(JSON.parse(source.textContent));}
 if(type==='master'&&/\.(csv|tsv)$/.test(name)){const rows=I._test.parseDelimited(text,name.endsWith('.tsv')?'tsv':'csv');return fromMasterTable(rows.map((values,i)=>({row:i+1,values})),file.name,hash);}
 throw Error('Use the supported XLSX layout or normalized JSON for this data type.');
}
async function prepareImport(file){const msg=$('#import-message');if(msg)msg.textContent=t('Reading locally and validating…','正在本地读取并检查…','正在本機讀取並檢查…');$('#import-preview').innerHTML='';staged=null;try{await load(X.feedType);if(!X[X.feedType])throw Error('Load the current snapshot before reviewing a refresh.');const type=X.feedType,data=await parseImport(file,type);staged={type,data};let details='';if(type==='master'){const diff=C.refreshDiff(X.master,data);details=stats([[diff.added,'Added'],[diff.changed,'Changed'],[diff.removed,'Removed from new snapshot'],[diff.retained,'Retained identities']]);}else if(type==='history')details=stats([[data.series.length,'Series'],[data.series.reduce((a,s)=>a+s.points.length,0),'Observations']]);else details=stats([[data.rows.length,'Source rows'],[data.quote_date?d(data.quote_date):'—','Quote date']]);$('#import-message').textContent=t('Preview ready. Nothing has been replaced.','预览已就绪，尚未替换任何数据。','預覽已就緒，尚未取代任何數據。');$('#import-preview').innerHTML=`<div class="review-box"><h3>${e(t('Import preview'))}</h3><p>${e(file.name)}</p>${details}<p class="v3-caption">${e(type==='master'?t('Saved identities remain saved. Missing identities stay flagged; snapshot-row fallback IDs do not migrate automatically.','已存身份保持不变，缺失身份保留提示；依赖快照行号的身份不会自动迁移。','已存身分保持不變，缺失身分保留提示；依賴快照列號的身分不會自動遷移。'):type==='ust'?t('The UST comparison tray will clear because source row IDs are not verified instrument identities.','国债比较栏将清空，因为来源行编号不是已核实证券身份。','國債比較列將清空，因為來源列編號並非已核實證券身分。'):t('The prior local snapshot is retained for rollback.','保留前一个本地快照以便恢复。','保留前一個本機快照以供還原。'))}</p><div class="links">${button('Apply reviewed snapshot','data-tool="apply-import"')}${button('Cancel','data-tool="cancel-import"','button ghost')}</div></div>`;}catch(err){if($('#import-message'))$('#import-message').textContent=t('Import rejected: ','导入被拒绝：','匯入遭拒：')+err.message;staged=null;}}
async function applyImport(){if(!staged)return;const {type,data}=staged,previous=X[type];try{await storeSnapshot('previous-'+type,previous);await storeSnapshot(type,data);}catch{dbFailed=true;toast(t('Storage failed. Snapshot applies only to this session.','存储失败，快照仅在当前会话有效。','儲存失敗，快照僅在目前工作階段有效。'));}X[type]=data;if(type==='ust'){X.ustCompare=[];persist();}if(type==='master')X.page=1;if(type==='history'){const ids=new Set(data.series.map(s=>s.id));if(!ids.has(X.historyA))X.historyA=data.series.find(s=>s.family==='ust')?.id||data.series[0].id;const end=data.series.flatMap(s=>s.points.map(p=>p[0])).sort().at(-1);if(end){X.end=end;X.curveA=end;}}staged=null;host.render();toast(t('Reviewed snapshot applied.','已应用检查后的快照。','已套用檢查後的快照。'));}
function showDialog(title,content){let dialog=$('#tool-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='tool-dialog';dialog.setAttribute('aria-label','Research detail');document.body.append(dialog);}if(dialog.open)dialog.close();dialog.innerHTML=`<div class="dialog-head"><h2 id="tool-title">${e(t(title))}</h2><button class="close" data-close="tool-dialog" aria-label="${e(t('Close'))}">×</button></div><div class="v3-detail">${content}</div>`;dialog.showModal();dialog.scrollTop=0;}
function watchDialog(ids){if(!ids.length)return;showDialog('Add to watchlist',`<form id="watch-form"><label class="field">${e(t('Existing list'))}<select id="watch-existing">${option('','Create new list','')}${X.watchlists.map(w=>option(w.id,w.name,'')).join('')}</select></label><label class="field section">${e(t('List name'))}<input id="watch-name" maxlength="100" placeholder="${e(t('List name'))}"></label><label class="field section">${e(t('Notes'))}<textarea id="watch-note" maxlength="2000"></textarea></label><input type="hidden" id="watch-ids" value="${e(JSON.stringify(ids))}"><div class="links"><button type="submit" class="button">${e(t('Save'))}</button></div></form>`);}
function screenDialog(){showDialog('Save screen',`<form id="screen-form"><label class="field">${e(t('Screen name'))}<input id="screen-name" maxlength="100" required></label><p class="v3-caption">${e(t('Stores current filter rules. The result count changes when a new snapshot is applied.','保存当前筛选规则，应用新快照后结果数量可能变化。','儲存目前篩選規則，套用新快照後結果數量可能改變。'))}</p><button class="button" type="submit">${e(t('Save'))}</button></form>`);}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){download('Market-Hub-Workspace-'+X.asof+'.json',{kind:'market-hub-workspace',schemaVersion:1,exportedAt:new Date().toISOString(),snapshotId:X.master?.snapshot.id||null,workspace:{selection:X.selection,watchlists:X.watchlists,screens:X.screens,notes:X.notes,ustCompare:X.ustCompare}});}
function validWorkspace(v){if(v?.kind!=='market-hub-workspace'||v.schemaVersion!==1||!v.workspace||!Array.isArray(v.workspace.selection)||!Array.isArray(v.workspace.watchlists)||!Array.isArray(v.workspace.screens)||!v.workspace.notes||typeof v.workspace.notes!=='object')throw Error('Expected a version 1 Market Hub workspace backup.');const w=v.workspace;if(w.selection.length>15000||w.watchlists.length>300||w.screens.length>300||w.selection.some(x=>typeof x!=='string'))throw Error('Invalid workspace counts or selection.');for(const a of w.watchlists)if(typeof a.id!=='string'||typeof a.name!=='string'||a.name.length>100||!Array.isArray(a.ids)||a.ids.length>15000||a.ids.some(x=>typeof x!=='string')||(a.note&&typeof a.note!=='string'))throw Error('Invalid watchlist.');for(const s of w.screens)if(typeof s.id!=='string'||typeof s.name!=='string'||!s.filters||typeof s.filters!=='object'||!Array.isArray(s.filters.categories)||!Array.isArray(s.filters.currencies)||s.filters.categories.some(x=>typeof x!=='string')||s.filters.currencies.some(x=>typeof x!=='string'))throw Error('Invalid saved screen.');for(const [k,x] of Object.entries(w.notes))if(k.length>1000||typeof x!=='string'||x.length>3000)throw Error('Invalid workspace notes.');return w;}
function restoreDialog(){showDialog('Restore backup',`<p>${e(t('Restore replaces saved lists, notes, filters and selections after you review. Market data is not included in workspace backups.','恢复操作将在检查后替换清单、备注、筛选与选择；工作区备份不包含市场数据。','還原操作將在檢查後取代清單、備註、篩選與選擇；工作區備份不包含市場數據。'))}</p><label class="field">${e(t('Restore backup'))}<input id="workspace-file" type="file" accept=".json"></label><div id="workspace-review" class="section" role="status"></div>`);}
let pendingWorkspace=null;
async function previewWorkspace(file){pendingWorkspace=null;try{if(!file||file.size>12*1024*1024)throw Error('Use a JSON backup below 12 MiB.');const v=JSON.parse(await file.text()),w=validWorkspace(v);pendingWorkspace=w;$('#workspace-review').innerHTML=notice(e(t('Replace current local workspace?','是否替换当前本地工作区？','是否取代目前本機工作區？')))+'<p>'+w.watchlists.length+' '+e(t('Watchlists'))+' · '+w.screens.length+' '+e(t('Saved screens'))+'</p>'+button('Apply reviewed workspace','data-tool="apply-workspace"');}catch(err){$('#workspace-review').textContent=err.message;}}

function rerenderResults(){if($('#master-result-area'))$('#master-result-area').innerHTML=resultArea();translateDOM();}
function rerenderUST(){if($('#ust-stats'))$('#ust-stats').innerHTML=stats([[X.ust.rows.length,'Source rows'],[ustRows().length,'Matching candidates'],[X.ust.quote_date?d(X.ust.quote_date):'—','Quote date'],[X.ustCompare.length+'/4','Selected']]);if($('#ust-results'))$('#ust-results').innerHTML=ustResults(ustRows());translateDOM();}
function resetMaster(){X.q='';X.categories=[];X.currencies=[];X.quote='';X.ar='';X.activeList=null;X.page=1;}
function setFilterFrom(saved){const f=saved||{};X.q=typeof f.q==='string'?f.q:'';X.categories=Array.isArray(f.categories)?f.categories.filter(x=>typeof x==='string'):[];X.currencies=Array.isArray(f.currencies)?f.currencies.filter(x=>typeof x==='string'):[];X.quote=typeof f.quote==='string'?f.quote:'';X.ar=typeof f.ar==='string'?f.ar:'';X.page=1;X.activeList=null;}
document.addEventListener('click',async ev=>{
 const det=ev.target.closest('[data-detail]');if(det){masterDetail(det.dataset.detail);return;}
 const b=ev.target.closest('[data-tool]');if(!b)return;const a=b.dataset.tool;ev.preventDefault();
 if(a==='tab'){X[b.dataset.key]=b.dataset.tab;if(b.dataset.key==='historyTab')X.scenario=0;host.render();}
 else if(a==='retry'){delete errors[b.dataset.type];load(b.dataset.type);}
 else if(a==='page'){X.page=Math.max(1,X.page+Number(b.dataset.step));rerenderResults();$('#master-count')?.scrollIntoView({block:'start',behavior:'instant'});}
 else if(a==='page-pick'){const ids=masterRows().slice((X.page-1)*24,X.page*24).map(r=>r.id);X.selection=[...new Set([...X.selection,...ids])];persist();rerenderResults();}
 else if(a==='clear-selection'){X.selection=[];persist();rerenderResults();}
 else if(a==='clear-filters'){resetMaster();host.render();}
 else if(a==='full-master'){X.activeList=null;X.page=1;host.render();}
 else if(a==='drill'){resetMaster();X.categories=[b.dataset.cat];X.currencies=[b.dataset.ccy];X.masterTab='explore';host.render();}
 else if(a==='review-cross'||a==='review-missing'||a==='review-zero'){resetMaster();if(a==='review-cross')X.quote='Crossed quote';else X.ar=a==='review-zero'?'zero':'missing';X.masterTab='explore';host.render();}
 else if(a==='explore'){X.masterTab='explore';host.render();}
 else if(a==='watch'){watchDialog([...X.selection]);}
 else if(a==='watch-one'){watchDialog([b.dataset.id]);}
 else if(a==='screen-save'){screenDialog();}
 else if(a==='saved-open'){const w=(b.dataset.kind==='watch'?X.watchlists:X.screens).find(x=>x.id===b.dataset.id);if(!w)return;resetMaster();if(b.dataset.kind==='watch')X.activeList=w.id;else setFilterFrom(w.filters);X.masterTab='explore';host.render();}
 else if(a==='saved-remove'){if(b.dataset.kind==='watch')X.watchlists=X.watchlists.filter(w=>w.id!==b.dataset.id);else X.screens=X.screens.filter(w=>w.id!==b.dataset.id);persist();host.render();}
 else if(a==='note-save'){const el=$('#security-note');if(el){X.notes[el.dataset.id]=el.value;persist();toast(t('Saved on this device.','已保存在此设备。','已儲存在此裝置。'));}}
 else if(a==='compare'){if(X.ustCompare.includes(b.dataset.id))X.ustCompare=X.ustCompare.filter(id=>id!==b.dataset.id);else{if(X.ustCompare.length>=4){toast(t('Compare up to four bonds.','最多比较四只债券。','最多比較四檔債券。'));return;}X.ustCompare.push(b.dataset.id);}persist();if($('#tool-dialog')?.open)$('#tool-dialog').close();rerenderUST();}
 else if(a==='compare-clear'){X.ustCompare=[];persist();rerenderUST();}
 else if(a==='ust-detail'){ustDetail(b.dataset.id);}
 else if(a==='ust-clear'){X.ustQ='';X.ustMin='';X.ustMax='';X.ustCoupon='';X.ustYield='';X.ustPositive=false;host.render();}
 else if(a==='ust-upload'){X.feedType='ust';host.navigate('feeds');}
 else if(a==='ust-history'){X.historyTab='curves';host.navigate('history');}
 else if(a==='apply-import'){await applyImport();}
 else if(a==='cancel-import'){staged=null;$('#import-preview').innerHTML='';$('#import-message').textContent=t('Cancelled. The previous snapshot is unchanged.','已取消，原快照保持不变。','已取消，原快照保持不變。');}
 else if(a==='rollback'){const type=X.feedType,previous=await stored('previous-'+type);if(!previous){toast(t('No previous local snapshot is available.','没有可恢复的上一份本地快照。','沒有可還原的上一份本機快照。'));return;}staged={type,data:validate(type,previous)};$('#import-preview').innerHTML=`<div class="review-box"><h3>${e(t('Rollback previous snapshot'))}</h3><p>${e(t('Review before replacing the current local snapshot.','替换当前本地快照前请先检查。','取代目前本機快照前請先檢查。'))}</p>${button('Apply reviewed snapshot','data-tool="apply-import"')}${button('Cancel','data-tool="cancel-import"','button ghost')}</div>`;}
 else if(a==='backup'){backup();}
 else if(a==='restore'){restoreDialog();}
 else if(a==='apply-workspace'&&pendingWorkspace){const w=pendingWorkspace;X.selection=[...new Set(w.selection)];X.watchlists=w.watchlists;X.screens=w.screens;X.notes=w.notes;X.ustCompare=Array.isArray(w.ustCompare)?w.ustCompare.filter(x=>typeof x==='string').slice(0,4):[];pendingWorkspace=null;persist();$('#tool-dialog').close();host.render();toast(t('Workspace restored.','工作区已恢复。','工作區已還原。'));}
});
document.addEventListener('submit',ev=>{if(ev.target.id==='watch-form'){ev.preventDefault();const ids=JSON.parse($('#watch-ids').value),existing=$('#watch-existing').value,name=$('#watch-name').value.trim(),note=$('#watch-note').value;if(existing){const w=X.watchlists.find(w=>w.id===existing);if(!w)return;w.ids=[...new Set([...w.ids,...ids])];if(note)w.note=note;}else{if(!name){$('#watch-name').focus();return;}X.watchlists.push({id:crypto.randomUUID(),name,ids:[...new Set(ids)],note,createdAt:new Date().toISOString()});}persist();$('#tool-dialog').close();host.render();toast(t('Watchlist saved.','自选清单已保存。','自選清單已儲存。'));}if(ev.target.id==='screen-form'){ev.preventDefault();const name=$('#screen-name').value.trim();if(!name)return;const f=masterFilter();delete f.ids;X.screens.push({id:crypto.randomUUID(),name,filters:f,createdAt:new Date().toISOString()});persist();$('#tool-dialog').close();toast(t('Screen saved.','筛选已保存。','篩選已儲存。'));}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='master-search'){X.q=el.value;X.page=1;rerenderResults();}if(el.id==='ust-search'){X.ustQ=el.value;rerenderUST();}});
document.addEventListener('change',async ev=>{const el=ev.target,id=el.id;
 if(id==='language'){lang=el.value;try{localStorage.setItem('market-hub-language',lang);}catch{}host.render();translateDOM();return;}
 if(el.dataset.facet){const key=el.dataset.facet;X[key]=el.checked?[...new Set([...X[key],el.value])]:X[key].filter(x=>x!==el.value);X.page=1;rerenderResults();return;}
 if(el.dataset.pick){const id=el.dataset.pick;X.selection=el.checked?[...new Set([...X.selection,id])]:X.selection.filter(x=>x!==id);persist();rerenderResults();return;}
 const masterKeys={'master-quote':'quote','master-ar':'ar','master-sort':'sort','master-precision':'precision'};if(masterKeys[id]){X[masterKeys[id]]=el.value;X.page=1;rerenderResults();return;}
 if(id==='history-series'){X[X.historyTab==='fx'?'fxA':'historyA']=el.value;host.render();}
 else if(id==='history-compare'){X[X.historyTab==='fx'?'fxB':'historyB']=el.value;host.render();}
 else if(id==='history-start'||id==='history-end'){const next=el.value;if(!C.validDate(next)||(id==='history-start'?next>X.end:next<X.start)){toast(t('Choose a valid ordered date range.','请选择有效且顺序正确的日期区间。','請選擇有效且順序正確的日期區間。'));host.render();return;}X[id==='history-start'?'start':'end']=next;host.render();}
 else if(id==='history-period'){const max=X.history.series.flatMap(s=>s.points.map(p=>p[0])).sort().at(-1);if(el.value==='custom')return;X.end=max;X.start=el.value==='all'?'1900-01-01':String(Number(max.slice(0,4))-Number(el.value))+max.slice(4);host.render();}
 else if(id==='fx-mode'){X.fxMode=el.value;host.render();}
 else if(id==='history-events'){X.events=el.checked;host.render();}
 else if(id==='history-scenario'){const v=Number(el.value),fx=X.historyTab==='fx';if(!Number.isFinite(v)||v<(fx?-80:-500)||v>(fx?200:500)){toast(t('Scenario input is outside the displayed bounds.','情景输入超出显示范围。','情境輸入超出顯示範圍。'));host.render();return;}X.scenario=v;host.render();}
 else if(id==='history-horizon'){X.horizon=Number(el.value);host.render();}
 else if(id==='curve-family'){X.curveFamily=el.value;host.render();}
 else if(id==='curve-a'||id==='curve-b'){X[id==='curve-a'?'curveA':'curveB']=el.value;host.render();}
 else if(id==='ust-asof'){if(C.validDate(el.value))X.asof=el.value;else toast(t('Choose a valid date.','请选择有效日期。','請選擇有效日期。'));host.render();}
 else if(id==='ust-convention'){X.ustConvention=el.value;rerenderUST();}
 else if(id==='ust-sort'){X.ustSort=el.value;rerenderUST();}
 else if(['ust-min','ust-max','ust-coupon','ust-yield'].includes(id)){const keys={'ust-min':'ustMin','ust-max':'ustMax','ust-coupon':'ustCoupon','ust-yield':'ustYield'};if(el.value!==''&&!Number.isFinite(Number(el.value)))return;X[keys[id]]=el.value;rerenderUST();}
 else if(id==='ust-positive'){X.ustPositive=el.checked;rerenderUST();}
 else if(id==='feed-type'){X.feedType=el.value;staged=null;$('#import-preview').innerHTML='';$('#import-message').textContent='';$('#data-file').value='';}
 else if(id==='data-file'&&el.files[0])await prepareImport(el.files[0]);
 else if(id==='workspace-file'&&el.files[0])await previewWorkspace(el.files[0]);
});
const originalNodes=new WeakMap(),originalAttributes=new WeakMap();let translating=false,queued=false;
function translateString(s){const lead=s.match(/^\s*/)[0],trail=s.match(/\s*$/)[0],trim=s.trim();if(!trim)return s;let value=MarketI18n[trim];if(value)return lead+value[lang==='zh-Hant'?1:0]+trail;const clean=trim.replace(/^[◫◈▤▣⌁⌕◇▦◒↻•]+\s*/,''),suffix=/\s*↗$/.test(clean)?' ↗':'',bare=clean.replace(/\s*↗$/,'');value=MarketI18n[bare];if(value)return lead+(trim.slice(0,trim.indexOf(clean)))+value[lang==='zh-Hant'?1:0]+suffix+trail;return s;}
function translateDOM(){if(translating)return;translating=true;try{document.documentElement.lang=lang;const l=$('#language');if(l)l.value=lang;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const parent=node.parentElement;if(!parent||parent.closest('script,style,textarea,input,select,#display-settings,[data-display-open],#reader-content,.raw-grid dd,.cell-number,.security-id,pre'))continue;const raw=originalNodes.get(node)||node.nodeValue;if(!originalNodes.has(node))originalNodes.set(node,raw);const next=lang==='en'?raw:translateString(raw);if(node.nodeValue!==next)node.nodeValue=next;}for(const el of document.querySelectorAll('[aria-label],[placeholder]')){if(el.closest('script,select,#display-settings,[data-display-open]'))continue;let attrs=originalAttributes.get(el);if(!attrs){attrs={};for(const a of ['aria-label','placeholder'])if(el.hasAttribute(a))attrs[a]=el.getAttribute(a);originalAttributes.set(el,attrs);}for(const [a,raw] of Object.entries(attrs)){const value=lang==='en'?raw:translateString(raw);if(el.getAttribute(a)!==value)el.setAttribute(a,value);}}}finally{translating=false;}}
function translationNote(){if(lang==='en')return'';return`<div class="translate-note">${e(t('Chinese navigation, controls and authored research summaries. Provider headlines, instrument names and original source reports retain their original language.','导航、控件和已编写的研究摘要提供中文；供应商标题、证券名称及原始来源报告保留原文。','導覽、控制項與已編寫的研究摘要提供中文；供應商標題、證券名稱及原始來源報告保留原文。'))}</div>`;}
function afterRender(view){if(['master','history','ust'].includes(view)&&!X[view])load(view);if(view==='feeds'&&!X[X.feedType])load(X.feedType);if(!$('#language-note')&&lang!=='en'){const div=document.createElement('div');div.id='language-note';div.innerHTML=translationNote();$('#view').prepend(div);}translateDOM();}
function reportChinese(){if(lang==='en')return;const reader=$('#reader-content');if(!reader||reader.querySelector('.translate-note'))return;const title=$('#reader-title')?.textContent||'',credit=/Bond|Credit|债券|債券/.test(title),summary=credit?t('The report distinguishes interest-rate risk, financing structures, liquidity and credit deterioration. Compare issuance terms with their dates and keep payment arrears separate from PIK and default.','本报告区分利率风险、融资结构、流动性与信用恶化。比较发行条款时须注意日期，并区分拖欠付款、PIK 与违约。','本報告區分利率風險、融資結構、流動性與信用惡化。比較發行條款時須留意日期，並區分拖欠付款、PIK 與違約。'):t('The earnings edition distinguishes reported results, guidance, cash flow periods and market reactions. Amazon’s trailing-twelve-month cash flow is not comparable to another company’s single quarter.','本财报简报区分已公布业绩、指引、现金流期间与市场反应。亚马逊过去十二个月现金流不可直接与其他公司的单季数字比较。','本財報簡報區分已公布業績、指引、現金流期間與市場反應。亞馬遜過去十二個月現金流不可直接與其他公司的單季數字比較。');const div=document.createElement('div');div.className='translate-note';div.innerHTML='<b>'+e(t('Chinese research summary'))+'</b><p>'+e(summary)+'</p><span>'+e(t('Original English'))+' ↓</span>';reader.prepend(div);}
function connect(api){host=api;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;translateDOM();if($('#reader')?.open)reportChinese();});});observer.observe(document.body,{childList:true,subtree:true});}
return{connect,afterRender,masterView,historyView,ustView,feedsView,welcome};
})();



